/**
 * Build the web favicon and PWA icon set from the canonical Vallo app icon.
 *
 * Run from the repository root:
 *
 *   node scripts/build-web-icons.mjs
 *
 * WHY THIS SCRIPT EXISTS.
 *
 * `scripts/build-native-icons.mjs` opens by recording that the icons under
 * `apps/web/public/pwa` "were generated by hand from the same source and there
 * is no record of how", and that whoever next changed the brand mark would have
 * to reverse engineer the padding, the background and the safe zone from the
 * pixels. The brand mark has now changed. This file is that record for the web
 * half, so the next change is a rerun rather than an archaeology exercise.
 *
 * THE SOURCE, AND WHY IT IS THE TILE RATHER THAN THE MARK.
 *
 * `brand/vallo-icon.png` is the supplied glass tile: a rounded square on deep
 * navy with an electric blue rim light, the five-tower skyline and the orbital
 * swoosh inside it, and the VALLO wordmark beneath. It is 1024x1024 and it was
 * cut from the founder's 1254x1254 render, so nothing here is enlarged.
 *
 * The old script had to cut the mark out of a lockup, because the old lockup
 * carried a wordmark and a tagline that turn to mush at 48px. This one does not
 * face that choice at the sizes that matter: the tile IS the icon, drawn as an
 * icon, and it is what the founder supplied.
 *
 * THE ONE PLACE THE WORDMARK IS A PROBLEM, NAMED RATHER THAN HIDDEN.
 *
 * At 16 and 32 pixels the VALLO wordmark inside the tile is a smudge, and both
 * app stores mark an icon down for small text. So the two favicon sizes are cut
 * from `brand/vallo-mark.png`, the skyline and swoosh alone, composed on the
 * brand navy. Every size from 48 up uses the whole tile, where the wordmark is
 * legible and is part of what makes the icon recognisable.
 *
 * THE MASKABLE ICON.
 *
 * Android launchers apply a circular or squircle mask and may crop up to 20 per
 * cent off each edge. A maskable icon must therefore hold everything meaningful
 * inside the middle 80 per cent, so this one scales the tile to 72 per cent of
 * the canvas and centres it on the navy. That is deliberately conservative: the
 * tile has its own rounded corners, and a rounded tile clipped by a rounded
 * mask looks like a mistake rather than a design.
 *
 * THE BACKGROUND IS NEVER TRANSPARENT.
 *
 * A transparent icon is painted onto whatever the launcher, the browser tab or
 * the bookmark bar feels like, and this brand is dark by default and must not
 * be read on white. Every file here is composed on `#010118`, the layer-1 base
 * navy in `packages/design-tokens/src/tokens.css`, which is the authority.
 */

import { mkdir, stat } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const BRAND = path.join(ROOT, "apps/web/public/brand");
const TILE = path.join(BRAND, "vallo-icon.png");
const MARK = path.join(BRAND, "vallo-mark.png");
const PWA = path.join(ROOT, "apps/web/public/pwa");

/** Sampled brand anchor. `tokens.css` layer 1 is the authority. */
const NAVY = { r: 1, g: 1, b: 24, alpha: 1 };

/** Below this many pixels the wordmark inside the tile stops being legible. */
const WORDMARK_FLOOR = 48;

/** Share of a maskable canvas the tile may occupy. Android crops up to 20 per cent. */
const MASKABLE_SCALE = 0.72;

const flat = (image) => image.flatten({ background: NAVY });

async function square(size, { source = TILE, inset = 0 } = {}) {
  const inner = Math.round(size * (1 - inset));
  const art = await flat(sharp(source).resize(inner, inner, { kernel: "lanczos3" }))
    .png()
    .toBuffer();
  if (inner === size) return art;
  const pad = Math.round((size - inner) / 2);
  return sharp({
    create: { width: size, height: size, channels: 4, background: NAVY },
  })
    .composite([{ input: art, top: pad, left: pad }])
    .png()
    .toBuffer();
}

async function write(name, buffer) {
  const target = path.join(PWA, name);
  await sharp(buffer).png({ compressionLevel: 9, palette: true }).toFile(target);
  const { size } = await stat(target);
  return { name, size };
}

await mkdir(PWA, { recursive: true });

const written = [];

/* The plain square icons. Small sizes drop the wordmark, per the note above. */
for (const size of [16, 32, 48, 64, 192, 512]) {
  const source = size < WORDMARK_FLOOR ? MARK : TILE;
  written.push(await write(`icon-${size}.png`, await square(size, { source })));
}

/* Apple's home screen icon. 180 is the size iOS actually asks for. */
written.push(await write("apple-touch-icon.png", await square(180)));

/* The maskable icon, held inside the safe zone. */
written.push(
  await write("icon-maskable-512.png", await square(512, { inset: 1 - MASKABLE_SCALE })),
);

/*
 * The favicon. A single 32px frame rather than a multi-size .ico: every browser
 * that matters reads PNG favicons, the manifest and the apple-touch-icon carry
 * the larger sizes, and a one-frame file is a third of the bytes on a network
 * where bytes are the point.
 */
await sharp(await square(32, { source: MARK }))
  .png({ compressionLevel: 9, palette: true })
  .toFile(path.join(ROOT, "apps/web/public/favicon.ico"));

console.log("Web icons, from brand/vallo-icon.png and brand/vallo-mark.png:");
for (const { name, size } of written) {
  console.log(`  pwa/${name.padEnd(24)} ${String(size).padStart(7)} bytes`);
}
console.log("  favicon.ico              from vallo-mark.png at 32px");
